static int cmp_int(const void* x, const void* y) {
    int a = *(const int*) x, b = *(const int*) y;
    return (a > b) - (a < b);
}

int middleReading(int* readings, int readingsSize) {
    int* a = malloc(readingsSize * sizeof(int));
    memcpy(a, readings, readingsSize * sizeof(int));
    qsort(a, readingsSize, sizeof(int), cmp_int);
    int answer = a[readingsSize / 2];
    free(a);
    return answer;
}

