class Solution {
    private final Random rng = new Random(5);

    public int middleReading(int[] readings) {
        int[] a = readings.clone();
        int target = a.length / 2;
        int lo = 0, hi = a.length - 1;
        while (true) {
            int p = a[lo + rng.nextInt(hi - lo + 1)];
            int lt = lo, i = lo, gt = hi;
            while (i <= gt) {
                if (a[i] < p) { int t = a[lt]; a[lt++] = a[i]; a[i++] = t; }
                else if (a[i] > p) { int t = a[gt]; a[gt--] = a[i]; a[i] = t; }
                else i++;
            }
            if (target < lt) hi = lt - 1;
            else if (target > gt) lo = gt + 1;
            else return p;
        }
    }
}

