int middleReading(int* readings, int readingsSize) {
    int n = readingsSize;
    int* a = malloc(n * sizeof(int));
    memcpy(a, readings, n * sizeof(int));
    int target = n / 2;
    int lo = 0, hi = n - 1, answer = 0;
    while (1) {
        int p = a[lo + rand() % (hi - lo + 1)];
        int lt = lo, i = lo, gt = hi;
        while (i <= gt) {
            if (a[i] < p) { int t = a[lt]; a[lt++] = a[i]; a[i++] = t; }
            else if (a[i] > p) { int t = a[gt]; a[gt--] = a[i]; a[i] = t; }
            else i++;
        }
        if (target < lt) hi = lt - 1;
        else if (target > gt) lo = gt + 1;
        else { answer = p; break; }
    }
    free(a);
    return answer;
}
